TLM.f("Sancti/05-18",{"officium":"S. Venantii Martyris","rule":["Gloria"],"fallback":"Commune/C2","from":{"Introitus":"Commune/C2","Lectio":"Commune/C2","Graduale":"Commune/C2","GradualeP":"Commune/C2","Tractus":"Commune/C2","Evangelium":"Commune/C2","Offertorium":"Commune/C2","Communio":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."}],"Oratio":[{"k":"text","la":"Deus, qui hunc diem beáti Venántii Mártyris tui triúmpho consecrásti: exáudi preces pópuli tui et præsta: ut, qui ejus mérita venerámur, fídei constántiam imitémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:34-42"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte arbitrári, quia pacem vénerim míttere in terram: non veni pacem míttere, sed gládium. Veni enim separáre hóminem advérsus patrem suum, et fíliam advérsus matrem suam, et nurum advérsus socrum suam: et inimíci hóminis doméstici ejus. Qui amat patrem aut matrem plus quam me, non est me dignus: et qui amat fílium aut fíliam super me, non est me dignus. Et qui non áccipit crucem suam, et séquitur me, non est me dignus. Qui invénit ánimam suam, perdet illam: et qui perdíderit ánimam suam propter me, invéniet eam. Qui récipit vos, me récipit: et qui me récipit, récipit eum, qui me misit. Qui récipit prophétam in nómine prophétæ, mercédem prophétæ accípiet: et qui récipit justum in nómine justi, mercédem justi accípiet. Et quicúmque potum déderit uni ex mínimis istis cálicem aquæ frígidæ tantum in nómine discípuli: amen, dico vobis, non perdet mercédem suam."}],"Offertorium":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum, Dómine."}],"Secreta":[{"k":"text","la":"Hanc oblatiónem, omnípotens Deus, beáti Venántii mérita tibi reddant accéptam: ut, ipsíus subsidiis adjuti, glóriæ ejus consortes efficiámur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:24"},{"k":"text","la":"Qui vult veníre post me, ábneget semetípsum, et tollat crucem suam, et sequátur me."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, ætérnæ vitæ sacraménta, te humiliter deprecántes: ut, beáto Venántio Mártyre tuo pro nobis deprecánte, véniam nobis concílient et grátiam."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ee67b476e9f36f4d":{"t":"Ps 63, 3, Ps 63, 2\n(Ps 63, 3) Zaštitio si me, Gospodine, od skupa zlikovaca, <i>aleluja</i>,\nod bezbožnoga mnoštva, <i>aleluja</i>, <i>aleluja</i>!\n(Ps 63, 2) Usliši, Gospodine, moju molitvu, jer se tebi molim. Ne daj da se moja duša straši neprijatelja!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 63, 3) Zaštitio si me, Gospodine, od skupa zlikovaca, <i>aleluja</i>,\nod bezbožnoga mnoštva, <i>aleluja</i>, <i>aleluja</i>!","kn":"(Ps. 63, 2). Štiti me. Bože, od gomile zloitvora. Alelujaod. mnoštva bezbožnoga, aleluja, aleluja. Usliši, Bože, moju molitvu, jer u Tebe se uzdam. izbavi moju dušu do straha neprijateljskoga. Slava Ocu . . . Štiti me . . .","knRef":"Kniewald 1942, str. 566–567 (snimka 284) (OCR)"},"6c9436b3c839672d":{"t":"<i>Pomolimo se</i>.\nBože, koji si ovaj dan posvetio slavnom pobjedom blaženog Venancija mučenika svoga, usliši molitve svoga naroda i podaj da nasljedujemo čvrstoću vjere onoga kojega zasluge častimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si ovaj dan posvetio pobjedom bi. Venancija, svoga mučenika, usliši molbe puka svoga i podaj, da nasljedujemo njegovu postojanost u svetoj vjeri, koji častimo njegove zasluge, po G. n.","knRef":"Kniewald 1942, str. 576–577 (snimka 289) (OCR)"},"c600ca35b26cf613":{"t":"Mudr 5, 1-5\nČitanje knjige Mudrosti. Pravednici će se junački održati protiv onih koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smest će se od užasnog straha i čudit će se neočekivanom njihovu spasu. Mislit će u sebi očajni i jecajući od duševne boli: To su oni kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima.","kn":"Čitanje knjige mudrosti (5, 1-5). Pravednici će se junački održati protiv -onih, koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smesti će se od užasnog straha 1 čudit će se neočekivanom njihovu spasu. Mislit će u sebi raskajani i jecajući od duševne boli: To su oni, kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"157b0d1d6a41242e":{"t":"Ps 88, 6, Ps 20, 4\n<i>Aleluja</i>, <i>aleluja</i>!\n(Ps 88, 6) Nebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>.\n(Ps 20, 4) Gospodine, okrunio si ga krunom od dragoga kamenja, <i>aleluja</i>.","kn":"Aleluja, aleluja! (Ps. 88, 6). Nebesa slave Tvoja čudesa. Gospodine, i Tvoju vjernost sveti pulc Tvoj, aleluja, aleluja! (Ps. 20, 4). Okrunio si ga, Gospodine, krunom dragoga kamenja, aleluja.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"443904ce684f9e74":{"t":"Iv 15, 1-7\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Ja sam pravi trs, a moj je Otac vinogradar. Svaku lozu na meni koja ne daje ploda uklonit će, a svaku koja daje plod očistit će da dade još više ploda. Vi ste već čisti radi riječi koju sam vam rekao. Ostanite u meni i ja u vama! Kao što loza sama od sebe ne može dati ploda, ako ne ostane na trsu, tako ni vi ako ne ostanete u meni. Ja sam trs, a vi loze. Tko ostaje u meni i ja u njemu, taj daje mnogo ploda. Bez mene ne možete činiti ništa. Tko ne ostane u meni izbacit će se kao loza koja se osuši, skupi, baca u oganj i izgori. Ako ostanete u meni, ostat će u vama i moje riječi: Štogod budete htjeli, tražite i dat će vam se!","kn":"t Slijedi sv. evanđelje po Ivanu (15, 1-7). U ono vrijeme reče Isus svojim učenicima: Ja sam pravi trs, a moj Otac je vinogradar. Svaku lozu na meni, koja ne daje ploda, uklonit će, a svaku, koja daje plod, očistit će, da dade još više ploda. Vi ste već čisti radi riječi, koju sam vam rekao. Ostanite u meni i ja u vama! Kao što loza sama od sebe ne može dati ploda, ako ne ostane na trsu, tako ni vi, ako ne ostanete na meni. Ja sam trs, a vi loze. Tko ostaje u meni i ja u njemu, taj daje mnogo ploda, jer bez mene ne možete činiti ništa. Tko ne ostane u meni, izbacit će se kao loza, koja se suši, i skupit će je, baciti u oganj 1 izgorjet će. Ako ostanete u meni, ostat će u vama i moje riječi: Štogod budete htjeli, ištite, i dat će vam se!","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"f6559b160ccd64cf":{"t":"Ps 88, 6\nNebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 88, 6). Nebesa slave čudesa Tvoja, Gospodine, i Tvoju vjernost sveti puk Tvoj, aleluja, aleluja.","knRef":"Kniewald 1942, str. 558–559 (snimka 280) (OCR)"},"ddd4e0b1411dd7d9":{"t":"Neka ti ovaj prinos, svemogući Bože, učine ugodnim zasluge blaženog Venancija, da potpomagani njegovim okriljem postanemo dionici njegove slave.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Zasluge bi. Venancija učinile Ti, svemogući Bože, ovaj prinos prijatnim, te njegovom pomoću postanemo dionici njegove slave, po G. n.","knRef":"Kniewald 1942, str. 578–579 (snimka 290) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka: Korizmeno predslovlje.","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"3042ea87cdaff402":{"t":"Ps 63, 11\nRaduje se pravednik u Gospodinu i pouzdaje se u njega i hvale se svi koji su pravedna srca, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 63, 11). Veseli se pravednik u Gospodinu i uzda se u njega i raduju se svi, koji su pravedna srca. Aleluja, aleluja.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"5d4c5e63ca6d6b8a":{"t":"<i>Pomolimo se</i>.\nPrimili smo, Gospodine, otajstva vječnog života ponizno te moleći da nam po molitvama blaženog Venancija mučenika tvoga isprose i oproštenje i milost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primismo, Gospodine, tajne vječnoga života ponizno Te moleći, da nam zagovorom bi. Venancija, mučenika Tvoga, isprose oproštenje i milost, po G. n.","knRef":"Kniewald 1942, str. 578–579 (snimka 290) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
